import type { Project, ProjectMode, Scene } from './types';

export interface DemoScript {
  id: ProjectMode;
  title: string;
  narration: string;
}

export const DEMO_SCRIPTS: Record<ProjectMode, DemoScript> = {
  factual: {
    id: 'factual',
    title: 'Sample factual script · Why we yawn',
    narration:
      'You are three hours into a long meeting when the first yawn escapes. Then someone across the table yawns too. For a long time, people assumed yawning was about oxygen: that a tired body needed a fresh gulp of air. That explanation has not held up. Researchers have measured oxygen and carbon dioxide in the blood of people who yawn, and found no clear difference. A more supported idea is temperature. A yawn pulls in cooler air and stretches the jaw, and it often happens when the brain is between states: waking, or getting sleepy. That does not fully explain why yawning spreads. Contagious yawning appears in humans and in some primates, and it shows up more in people who score higher on empathy measures. So the honest answer is that yawning is probably several things at once: a stretch, a cooling reflex, and a social signal we are still learning to read.',
  },
  fiction: {
    id: 'fiction',
    title: 'Sample fiction script · The night bus',
    narration:
      'The night bus ran one route and one route only, and Mira had never seen it stop for anyone else. It arrived at eleven, doors breathing open, a smell of rain and warm plastic inside. She climbed on with her folded map and sat where she always sat, three rows back, and watched the city dim. On the fourth night, someone was already there: a boy in a red coat, asleep against the window with his ticket held in his fist. Mira had spent a month trying not to look at anyone. She looked at him. The bus turned a corner that did not exist on her map, and the street outside became water, and the boy did not move. Then the doors opened, and a voice she knew very well said her name. She did not stand up. She said, instead, the first true sentence she had told anyone in a year: I am not ready to go home yet.',
  },
};

