/** The optional sample project, flagged with isSample so the UI can label it. */
export function createSampleProject(options: { now?: string; id?: string } = {}): Project {
  const now = options.now ?? new Date().toISOString();
  const script = DEMO_SCRIPTS.factual.narration;
  const scenes = sampleScenes();
  return {
    schemaVersion: SCHEMA_VERSION,
    id: options.id ?? newId('prj'),
    title: 'Sample · Why we yawn',
    createdAt: now,
    updatedAt: now,
    contentRevision: 0,
    isSample: true,
    brief: createEmptyBrief({
      topic:
        'Why yawning is contagious, and what the evidence actually supports. Why do we yawn?',
      audience: 'Curious adults who watch short explainers',
      goal: 'Leave knowing the oxygen explanation is weak and the temperature idea is better supported',
      mode: 'factual',
      targetDuration: 60,
      tone: 'Calm and curious, no hype',
      visualPreset: 'clean-educational',
      voicePreference: {
        label: 'Warm narrator, mid pace',
        notes: 'Configuration only — narration generation is not connected.',
      },
      budget: { amount: null, currency: 'USD' },
    }),
    script: {
      narration: script,
      fingerprint: computeScriptFingerprint(script),
      locked: false,
      lockedAt: null,
      updatedAt: now,
      versions: [],
    },
    sourceNotes: [
      {
        id: newId('src'),
        title: 'Sample source note (user-provided and unverified)',
        url: '',
        excerpt:
          'This is placeholder reference text shipped with the sample project. It is not a retrieved quotation.',
        notes: 'Replace with your own source before treating anything here as verified.',
      },
    ],
    storyNotes: { characters: '', setting: '', continuity: '' },
    audio: createEmptyProjectAudio(),
    planningNotes: [],
    storyboard: {
      scenes,
      reviewedScriptFingerprint: null,
      reviewedAt: null,
      previous: null,
    },
    workflow: { lastStage: 'brief' },
  };
}
